expected_output:
AOF 混合持久化(aof-use-rdb-preamble yes):
  文件头: RDB 全量快照 {'a': 1, 'b': 2}
  文件尾: AOF 增量 [('SET', 'c', 3), ('DEL', 'a', None)]
  恢复结果: {'b': 2, 'c': 3}
  优势: 兼具 RDB 快速加载 + AOF 低数据丢失

code:
def mix_persist(snapshot, incremental):
    return {"type": "RDB", "data": snapshot, "aof_tail": incremental}

snapshot = {"a": 1, "b": 2}
incremental = [("SET", "c", 3), ("DEL", "a", None)]
f = mix_persist(snapshot, incremental)
print("AOF 混合持久化(aof-use-rdb-preamble yes):")
print("  文件头: RDB 全量快照", f["data"])
print("  文件尾: AOF 增量", f["aof_tail"])
# 恢复: 先按 RDB 载入快照, 再重放 AOF 增量
restored = dict(f["data"])
for op, k, v in f["aof_tail"]:
    if op == "SET":
        restored[k] = v
    else:
        restored.pop(k, None)
print("  恢复结果:", restored)
print("  优势: 兼具 RDB 快速加载 + AOF 低数据丢失")
